// Diagnosis.js
import React from 'react';
import "./navleft.css";
import { ReactComponent as ReportIcon } from '../assets/icons/report.svg';
import { ReactComponent as SettingIcon } from '../assets/icons/setting.svg';
import { ReactComponent as LogoutIcon } from '../assets/icons/logout.svg';

export default function NavLeft(){
  return (
    <div className="nav__left">
        <div className="nav__left--avatar"></div>
        <div className="nav__left--func">
            <div className="nav__left--head"></div>
            <div className="nav__left--bottom">
                <div className="icon">
                    <SettingIcon className="icon--element" width="25" height="25"/>
                </div>
                <div className="icon">
                    <LogoutIcon className="icon--element" width="25" height="25"/>
                </div>
                <div className="icon">
                    <ReportIcon className="icon--element" width="25" height="33"/>
                </div>
            </div>
        </div>
    </div>
  );
};
